target.css:
:root {
  --paper: #fffdf8;
  --ink: #24313a;
  --line: #d9e1e3;
  --coral: #e85d55;
  --muted: #61717a;
}

.ladder-card {
  width: 460px;
  box-sizing: border-box;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 16px;
}

.card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  border-bottom: 1px solid var(--line);
  padding-bottom: 12px;
}

.paddle {
  font-size: 28px;
  line-height: 1;
}

h1 {
  margin: 0;
  color: var(--ink);
  font-size: 20px;
  line-height: 1.2;
}

.match-date {
  margin: 12px 0;
  color: var(--muted);
  font-size: 14px;
}

button {
  background: var(--coral);
  color: var(--paper);
  border: 0;
  border-radius: 8px;
  padding: 9px 14px;
  font-size: 14px;
  font-weight: 700;
}
